local showChronicles = Action()

function showChronicles.onUse(player, item, fromPosition, target, toPosition, isHotkey)
    local window = ModalWindow {
        title = "Cartas e Documentos Perdidos",
        message = "Selecione um documento para ler:" 
    }

    for _, title in ipairs(chronicleOrder) do
        window:addChoice(title, function(player, button, choice)
            local descriptionWindow = ModalWindow {
                title = title,
                message = chronicles[title]
            }
            descriptionWindow:addButton("Fechar")
            descriptionWindow:setDefaultEscapeButton(0)
            descriptionWindow:sendToPlayer(player)
        end)
    end

    window:addButton("Fechar")
    window:setDefaultEscapeButton(0)
    window:sendToPlayer(player)
end

